// Función para normalizar nombres (elimina acentos y caracteres especiales)
export const normalizeName = (str) => {
  return str
    .normalize("NFD") // Descompone los caracteres acentuados
    .replace(/[\u0300-\u036f]/g, "") // Elimina los diacríticos
    .replace(/[^\w\s-]/g, "") // Elimina caracteres especiales
    .replace(/\s+/g, "-") // Reemplaza espacios con guiones
    .toLowerCase(); // Convierte a minúsculas
};

const INLINE_REGEX = /(\*\*_(.+?)_\*\*|\*\*(.+?)\*\*|\*(.+?)\*)/g;

export function renderTextWithStyles(text) {
  if (text == null) return null;

  const out = [];
  let last = 0;
  let m;

  while ((m = INLINE_REGEX.exec(text)) !== null) {
    const [match, gAll, gBoldItalic, gBold, gItalic] = m;
    const start = m.index;

    // Texto plano previo al match
    if (start > last) out.push(text.slice(last, start));

    // **_bold+italic_**
    if (gBoldItalic != null) {
      out.push(
        <strong key={`bi-${start}`}>
          <em>{gBoldItalic}</em>
        </strong>
      );
    }
    // **bold**
    else if (gBold != null) {
      out.push(<strong key={`b-${start}`}>{gBold}</strong>);
    }
    // *italic*
    else if (gItalic != null) {
      out.push(<em key={`i-${start}`}>{gItalic}</em>);
    }

    last = start + match.length;
  }

  // Resto del texto
  if (last < text.length) out.push(text.slice(last));

  return out;
}

// === Bloques: párrafos, listas (líneas que empiezan con "* ") y saltos de línea ===
export function renderDescription(description, { listClassName } = {}) {
  if (!description) return null;

  const lines = String(description).split("\n");

  const blocks = [];
  let listBuffer = [];

  const flushList = () => {
    if (listBuffer.length === 0) return;
    blocks.push(
      <ul key={`ul-${blocks.length}`} className={listClassName}>
        {listBuffer.map((li, idx) => (
          <li key={`li-${blocks.length}-${idx}`}>{li}</li>
        ))}
      </ul>
    );
    listBuffer = [];
  };

  lines.forEach((rawLine, idx) => {
    const line = rawLine; // no trim global para no perder espacios deliberados
    const isBullet = /^\s*\*\s+/.test(line); // "* " al inicio (permite espacios antes)

    if (isBullet) {
      // Extrae el contenido posterior a "* "
      const content = line.replace(/^\s*\*\s+/, "");
      listBuffer.push(renderTextWithStyles(content));
      return;
    }

    // Si veníamos acumulando una lista y se cortó, la volcamos
    if (listBuffer.length) flushList();

    // Línea en blanco => salto de línea visual
    if (line.trim() === "") {
      blocks.push(<br key={`br-${idx}`} />);
      return;
    }

    // Párrafo normal
    blocks.push(
      <p key={`p-${idx}`} style={{ margin: "0.5rem 0" }}>
        {renderTextWithStyles(line)}
      </p>
    );
  });

  // Lista al final del texto
  if (listBuffer.length) flushList();

  return blocks;
}